SET local check_function_bodies = off;

CREATE TABLE "public"."keep_alive" (
  "id"        bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "pinged_at" timestamp with time zone DEFAULT now(),
  CONSTRAINT "keep_alive_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."keep_alive"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."paciente" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "codinome"     text                     NOT NULL,
  "psicologo_id" uuid,
  "idade"        bigint,
  CONSTRAINT "paciente_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."paciente"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."psicologo" (
  "id"         uuid                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "nome"       text,
  CONSTRAINT "psicologo_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."psicologo"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."sessao_terapia" (
  "id"                  bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "data"                timestamp with time zone NOT NULL DEFAULT now(),
  "paciente_id"         bigint                   NOT NULL,
  "emoji"               text,
  "palavra_selecionada" text,
  "palavra_livre"       text,
  "desenho"             jsonb,
  CONSTRAINT "sessao_terapia_pkey" PRIMARY KEY (id),
  "psicologo_id"        uuid                     NOT NULL DEFAULT auth.uid()
);

ALTER TABLE "public"."sessao_terapia"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  AS $function$
begin
  insert into public.psicologo (id, nome)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'nome', 'Novo Psicólogo')
  );
  return new;
end;
$function$;

ALTER TABLE "public"."psicologo"
  ADD CONSTRAINT "psicologo_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "public"."paciente"
  ADD CONSTRAINT "paciente_psicologo_id_fkey" FOREIGN KEY (psicologo_id) REFERENCES public.psicologo(id) ON DELETE CASCADE;

ALTER TABLE "public"."sessao_terapia"
  ADD CONSTRAINT "sessao_terapia_paciente_id_fkey" FOREIGN KEY (paciente_id) REFERENCES public.paciente(id) ON DELETE CASCADE;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

CREATE POLICY "permitir_leitura_publica" ON "public"."keep_alive"
  FOR SELECT
  TO "anon"
  USING (true);

CREATE POLICY "psicologo_delete_paciente" ON "public"."paciente"
  FOR DELETE
  TO "authenticated"
  USING ((auth.uid() = psicologo_id));

CREATE POLICY "psicologo_insert_paciente" ON "public"."paciente"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((auth.uid() = psicologo_id));

CREATE POLICY "psicologo_select_paciente" ON "public"."paciente"
  FOR SELECT
  TO "authenticated"
  USING ((auth.uid() = psicologo_id));

CREATE POLICY "psicologo_update_paciente" ON "public"."paciente"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() = psicologo_id))
  WITH CHECK ((auth.uid() = psicologo_id));

CREATE POLICY "Permitir leitura do próprio perfil" ON "public"."psicologo"
  FOR SELECT
  TO "authenticated"
  USING ((auth.uid() = id));

GRANT EXECUTE ON FUNCTION "public"."handle_new_user"() TO PUBLIC, "anon", "authenticated";

REVOKE ALL ON FUNCTION "public"."handle_new_user"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."handle_new_user"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."handle_new_user"() TO "service_role";

REVOKE ALL ON SEQUENCE "public"."keep_alive_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."keep_alive_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."keep_alive_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."keep_alive_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."keep_alive_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."keep_alive_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."keep_alive_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."keep_alive_id_seq" TO "service_role";

REVOKE ALL ON SEQUENCE "public"."paciente_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."paciente_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."paciente_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."paciente_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."paciente_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."paciente_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."paciente_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."paciente_id_seq" TO "service_role";

REVOKE ALL ON SEQUENCE "public"."sessao_terapia_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."sessao_terapia_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."sessao_terapia_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."sessao_terapia_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."sessao_terapia_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."sessao_terapia_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."sessao_terapia_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."sessao_terapia_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."keep_alive" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."keep_alive" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."keep_alive" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."keep_alive" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."paciente" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."paciente" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."paciente" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."paciente" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."psicologo" TO "anon", "authenticated";

