GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."sessao_terapia" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."sessao_terapia" TO "service_role";

ALTER TABLE "public"."sessao_terapia"
  ADD CONSTRAINT "sessao_terapia_psicologo_id_fkey" FOREIGN KEY (psicologo_id) REFERENCES public.psicologo(id) ON DELETE CASCADE;

CREATE POLICY "PSICOLOGO_GRAVA_PROPIA_SESSAO" ON "public"."sessao_terapia"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((psicologo_id = auth.uid()));

CREATE POLICY "PSICOLOGO_LE_PROPIA_SESSAO" ON "public"."sessao_terapia"
  FOR SELECT
  TO "authenticated"
  USING ((psicologo_id = auth.uid()));

